// One signature row: the signer's SPKI, the algorithm, the TBS content
// and the signature over its SEQUENCE header and content.
typedef struct {
    const char *name;
    const uint8_t *spki;
    size_t spki_len;
    uint8_t sigalg;
    const uint8_t *tbs;
    size_t tbs_len;
    const uint8_t *sig;
    size_t sig_len;
} webpki_signature_vector;

